(()=>{let filter='all',adminQueue='unassigned';const customerGroup=status=>status==='completed'?'completed':['cancelled','declined'].includes(status)?'cancelled':'progress',adminGroup=status=>['requested','assigned'].includes(status)?'open':status==='completed'?'done':['cancelled','declined'].includes(status)?'cancelled':'progress';const labels={all:'All',open:'Open',progress:'In progress',done:'Done',cancelled:'Cancelled',completed:'Completed'};const open=id=>{selected=id;view='home';render();};
 function rows(bookings,group){return bookings.length?bookings.map(ticket=>`<div class="ticket-row"><button type="button" class="ticket-main" data-ticket-open="${ticket.id}"><span><strong>${esc(svc(ticket.service).en)}</strong><small>${esc(ticket.village)} · ${esc(ticket.id)}</small></span><span class="ticket-status ${group(ticket.status)}">${esc(status(ticket))}</span></button>${role==='admin'?`<button type="button" class="quiet ticket-assign" data-ticket-open="${ticket.id}">${ticket.technicianId?'Change technician':'Assign technician'}</button>`:''}</div>`).join(''):'<p class="muted">No tickets in this section.</p>';}
 function adminList(){const all=data.bookings||[],unassigned=all.filter(x=>!x.technicianId),assigned=all.filter(x=>x.technicianId),source=adminQueue==='unassigned'?unassigned:assigned,shown=filter==='all'?source:source.filter(x=>adminGroup(x.status)===filter),counts={all:source.length,open:source.filter(x=>adminGroup(x.status)==='open').length,progress:source.filter(x=>adminGroup(x.status)==='progress').length,done:source.filter(x=>adminGroup(x.status)==='done').length,cancelled:source.filter(x=>adminGroup(x.status)==='cancelled').length};app.innerHTML=`<button class="back" id="tickets-back">← Admin dashboard</button><div class="intro"><div><div class="eyebrow">ADMIN TICKETS</div><h1>Task control</h1><p>Assign technicians and track every service request.</p></div></div><section class="card tickets-card"><div class="queue-tabs"><button data-queue="unassigned" class="${adminQueue==='unassigned'?'active':''}">Unassigned tasks <b>${unassigned.length}</b></button><button data-queue="assigned" class="${adminQueue==='assigned'?'active':''}">Assigned tasks <b>${assigned.length}</b></button></div><div class="ticket-filters">${Object.keys(counts).map(id=>`<button class="${filter===id?'active':''}" data-ticket-filter="${id}">${labels[id]}<b>${counts[id]}</b></button>`).join('')}</div><div class="ticket-list">${rows(shown,adminGroup)}</div></section>`;bindList();}
 function customerList(){const all=data.bookings||[],shown=filter==='all'?all:all.filter(x=>customerGroup(x.status)===filter),counts={all:all.length,progress:all.filter(x=>customerGroup(x.status)==='progress').length,completed:all.filter(x=>customerGroup(x.status)==='completed').length,cancelled:all.filter(x=>customerGroup(x.status)==='cancelled').length};app.innerHTML=`<button class="back" id="tickets-back">← Home</button><div class="intro"><div><div class="eyebrow">MY TICKETS</div><h1>Service requests</h1><p>${role==='technician'?'Tickets assigned to you.':'Track every request in one place.'}</p></div><span class="pill">${counts.all} total</span></div><section class="card tickets-card"><div class="ticket-filters">${Object.keys(counts).map(id=>`<button class="${filter===id?'active':''}" data-ticket-filter="${id}">${labels[id]}<b>${counts[id]}</b></button>`).join('')}</div><div class="ticket-list">${rows(shown,customerGroup)}</div></section>`;bindList();}
 function bindList(){document.querySelector('#tickets-back').onclick=()=>{view='home';render();};app.querySelectorAll('[data-ticket-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.ticketFilter;role==='admin'?adminList():customerList();});app.querySelectorAll('[data-queue]').forEach(b=>b.onclick=()=>{adminQueue=b.dataset.queue;filter='all';adminList();});app.querySelectorAll('[data-ticket-open]').forEach(b=>b.onclick=()=>open(b.dataset.ticketOpen));}
 function customerHome(){const card=[...document.querySelectorAll('.card')].find(x=>x.querySelector('h3')?.textContent.includes('Your service requests'));if(!card)return;const all=data.bookings||[],active=all.filter(x=>customerGroup(x.status)==='progress').length;card.innerHTML=`<div class="eyebrow">MY TICKETS</div><h3>Keep track of your service requests</h3><p class="muted">${all.length?`${active} in progress · ${all.filter(x=>customerGroup(x.status)==='completed').length} completed · ${all.filter(x=>customerGroup(x.status)==='cancelled').length} cancelled`:'Your requests will appear here once you book a service.'}</p><button type="button" class="secondary" id="open-tickets">Open My Tickets →</button>`;document.querySelector('#open-tickets').onclick=()=>{view='tickets';render();};}
 const baseRender=render;render=function(){baseRender();if(!localToken||!localUser||!data)return;if(view==='tickets'){role==='admin'?adminList():customerList();}else if(role==='customer'&&view==='home')customerHome();};})();
